def icon(name='star'):
 paths={'heart':'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z','video':'M15 8l6-3v14l-6-3M3 5h12v14H3Z','chat':'M21 11a9 9 0 0 1-9 9H3l1.8-4A9 9 0 1 1 21 11ZM8 10h8M8 14h5','mail':'M3 5h18v14H3ZM3 6l9 7 9-7','star':'m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z','leaf':'M20 3C8 2 2 8 5 15s16 5 15-12ZM5 20 16 8','path':'M4 21c0-8 16-2 16-10S4 10 4 3M1 6l3-3 3 3','sun':'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0','people':'M16 20v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.9M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0m4-3a4 4 0 0 1 0 8','check':'m5 12 4 4L19 6','moon':'M20 15a8.5 8.5 0 0 1-11-11 9 9 0 1 0 11 11Z','arrow':'M4 12h16m-6-6 6 6-6 6','lock':'M6 10h12v11H6ZM8 10V6a4 4 0 0 1 8 0v4','gift':'M3 8h18v5H3Zm2 5v8h14v-8M12 8v13M12 8C3 9 4 1 8 3c3 1 4 5 4 5s1-4 4-5c4-2 5 6-4 5'}
 return f'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="{paths.get(name,paths["star"])}"/></svg>'
def link(url,text,cls=''):return f'<a href="{url}" class="{cls}">{text}</a>'
def btn(text,url='/book',secondary=False):return link(url,text+icon('arrow'),'button'+(' secondary' if secondary else ''))
def avatar(cls=''):return f'<span class="avatar {cls}" aria-label="Amy portrait placeholder">A</span>'
def portrait():return '<div class="portrait"><span class="portrait-stars">✧</span><span class="initial">A</span><small>[Amy’s portrait]</small><div class="portrait-name">'+avatar()+'<span><strong>Amy</strong><small>Intuitive reader · Red Wing, MN</small></span>'+icon('star')+'</div></div>'
def intro(title,desc,eyebrow='A little space for clarity'):
 return f'<section class="inner-hero"><div class="wrap"><div class="breadcrumb"><a href="/">Home</a><span>/</span>{esc(title)}</div><p class="eyebrow">{eyebrow}</p><h1>{title}</h1><p class="lead">{desc}</p></div><span class="orb"></span></section>'
def heading(kicker,title,copy=''):return f'<div class="section-heading"><p class="eyebrow">{kicker}</p><h2>{title}</h2>'+ (f'<p>{copy}</p>' if copy else '')+'</div>'
def topics():return '<div class="topics">'+''.join(link('/book/?topic='+quote(t),icon(i)+f'<span>{t}</span>','topic') for t,i in zip(TOPICS,['heart','leaf','path','people','star','sun']))+'</div>'
def readingcards():
 out='<div class="grid three reading-cards">'
 for i,(typ,title,desc,opts) in enumerate([('video','Live video','Face to face, from the comfort of home.',['20 min','40 min','60 min']),('chat','Live chat','A private conversation, one message at a time.',['15 min','30 min']),('email','Email reading','Thoughtful words to return to, delivered within 48 hours.',['1 question','3 questions'])]):
  out+=f'<article class="reading-card" data-reading="{typ}"><div class="reading-art art-{typ}">{icon(typ if typ!="email" else "mail")}<span>{["A moment, face to face","Space to put it into words","A letter, just for you"][i]}</span></div><div class="card-body"><p class="eyebrow">{["Connect in the moment","Your words. Your pace.","Reflect in your own time."][i]}</p><h3>{title}</h3><p>{desc}</p><div class="pills duration-options">'+''.join(f'<button class="pill {"selected" if j==0 else ""}" data-duration="{o.split()[0]}" aria-pressed="{str(j==0).lower()}">{o}</button>' for j,o in enumerate(opts))+f'</div><div class="price"><strong>[PRICE]</strong><small data-price-caption>{opts[0]} · Amy to confirm</small></div><a class="button full reading-book" href="/book?type={typ}&duration={opts[0].split()[0]}">{["Book video reading","Book chat reading","Request email reading"][i]}{icon("arrow")}</a><a class="text-link" href="/readings/{typ}">Explore {typ} readings {icon("arrow")}</a></div></article>'
 return out+'</div>'
