def tarotfan(full=False):return '<div class="tarot-experience"><p class="small muted">Take a breath. Let one card catch your attention.</p><div class="tarot-fan">'+''.join(f'<button class="tarot-pull" style="--i:{i-3}" aria-label="Reveal today’s card, choice {i+1}"><img src="/assets/card-back.svg" alt="Lavender tarot card with a crescent moon" width="240" height="380" loading="lazy"></button>' for i in range(7))+'</div><div class="tarot-result" aria-live="polite"></div><p class="small muted">A moment of reflection. A possibility, not a prediction.</p></div>'
