def aboutblock():return '<section class="band lavender"><div class="wrap split about-block"><div>'+portrait()+'</div><div><p class="eyebrow">A real connection starts here</p><h2>Hi, I’m Amy.</h2><p class="lead">A little perspective can make room for a different kind of tomorrow.</p><p>[How Amy discovered her gift]</p><p>[Her approach to readings and what clients can expect]</p><blockquote>“[Amy’s own words about her approach to guidance.]”</blockquote>'+btn('Get to know Amy','/about',True)+'</div></div></section>'
