def articlecards():return '<div class="grid three article-grid">'+''.join(f'<article class="article-card" data-category="{a["category"]}" data-title="{esc(a["title"].lower())}"><a href="/journal/{a["slug"]}" class="article-image"><img src="/assets/still-life.svg" alt="Original pastel illustration of a candle, tarot card, and botanical branch" loading="lazy"></a><div class="card-body"><p class="eyebrow">{a["category"]} · 5 min read</p><h3><a href="/journal/{a["slug"]}">{a["title"]}</a></h3><p>{a["intro"]}</p>{link("/journal/"+a["slug"],"Read the journal "+icon("arrow"),"text-link")}</div></article>' for a in ARTICLES)+'</div>'
def formfield(label,name,typ='text',required=True,options=None):
 id='field-'+name
 if typ=='textarea':inp=f'<textarea id="{id}" name="{name}" maxlength="500" rows="5" {"required" if required else ""}></textarea><small class="counter">0 / 500</small>'
 elif typ=='select':inp=f'<select id="{id}" name="{name}">'+''.join(f'<option>{esc(o)}</option>' for o in options)+'</select>'
 else:inp=f'<input id="{id}" type="{typ}" name="{name}" {"required" if required else ""} '+('minlength="8" ' if typ=='password' else '')+f'autocomplete="{"email" if typ=="email" else "new-password" if typ=="password" else "off"}">'
 return f'<div class="field"><label for="{id}">{label}{" <span>(optional)</span>" if not required else ""}</label>{inp}</div>'
