page('/horoscopes','Horoscopes','A seasonal prompt for every sign.',intro('Look up. Look within.','A little cosmic perspective for your everyday life.','Horoscopes')+'<section class="section wrap"><p class="note">Original sample reflections for entertainment. These are not personalized predictions.</p>'+periodtabs()+'<p class="period-intro" aria-live="polite">Today: notice the small choice that deserves a little more attention.</p>'+signsgrid()+'<form id="sign-finder" class="panel narrow"><h3>Find your sign.</h3>'+formfield('Your birthday','birthday','date')+'<button class="button">Find my sign '+icon('star')+'</button></form>'+newsletter()+'</section>')
