def header(route):return '<a class="skip-link" href="#main">Skip to content</a><div class="utility"><span>Readings by video, chat & email</span><span>A little perspective. A space for you.</span><div><button data-chat><i class="online-dot"></i> Demo chat</button>'+link('/login','Sign in','auth-link')+'</div></div><header class="main-header"><a href="/" class="brand" aria-label="Amy Intuitive Readings home"><span>amy<span class="brand-star">✧</span></span><small>INTUITIVE READINGS</small></a><nav aria-label="Main navigation">'+''.join('<div class="nav-drop">'+link(u,t,'active' if route==u or (u!='/about' and route.startswith(u+'/')) else '')+(('<button class="mega-toggle" aria-label="Explore readings menu" aria-expanded="false">⌄</button><div class="mega-menu" hidden><div><p class="eyebrow">Ways to connect</p>'+''.join(link('/readings/'+x,x.title()+' readings') for x in ['video','chat','email'])+'</div><div><p class="eyebrow">What’s on your mind?</p>'+''.join(link('/book/?topic='+quote(t),t) for t in TOPICS)+'</div><div class="mega-feature">'+avatar()+'<h3>Your reading with Amy</h3><p>A personal space for a new perspective.</p>'+btn('Find your reading')+'</div></div>') if u=='/readings' else '')+'</div>' for u,t in NAV)+'</nav><div class="header-right"><span class="header-moon" data-moon title="Approximate moon phase over Red Wing"></span>'+btn('Book a reading')+'<button class="menu-toggle" aria-label="Open navigation" aria-expanded="false">☰</button></div></header>'
