 doc='<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#FBF8F5"><meta name="robots" content="noindex,nofollow"><title>'+esc(title)+' | Amy Intuitive Readings</title><meta name="description" content="'+esc(desc)+'"><meta property="og:title" content="'+esc(title)+'"><meta property="og:description" content="'+esc(desc)+'"><meta property="og:type" content="website"><meta property="og:url" content="'+origin+route+'"><meta property="og:image" content="'+origin+'/assets/social.png"><link rel="canonical" href="'+origin+route+'"><link rel="icon" href="/assets/card-back.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/tokens.css"><link rel="stylesheet" href="/assets/styles.css"><script type="application/ld+json">'+json.dumps(schema)+'</script><script defer src="/assets/data.js"></script><script defer src="/assets/services.js"></script><script defer src="/assets/app.js"></script></head><body data-page="'+route+'">'+header(route)+'<main id="main" tabindex="-1">'+body+(closing() if close else '')+'</main>'+footer()+'</body></html>'
 doc=re.sub(r'href="(/[^"?#]*)([?][^"#]*)?([#][^"]*)?"',lambda m:'href="'+(m[1] if m[1].endswith('/') or '.' in m[1].split('/')[-1] else m[1]+'/')+(m[2] or '')+(m[3] or '')+'"',doc)
 p.write_text(doc)
